<dialog id="confirm-action" class="confirm-dialog" aria-labelledby="confirm-title" aria-describedby="confirm-message"><h2 id="confirm-title">Konfirmasi tindakan</h2><p id="confirm-message" data-confirm-message></p><dl class="detail" aria-label="Ringkasan tindakan"></dl><div class="actions"><button type="button" class="button secondary" data-confirm-cancel>Batal</button><button type="button" class="button" data-confirm-accept>Konfirmasi</button></div></dialog>
<div id="feedback" class="feedback-toast notice success" role="status" aria-live="polite" aria-atomic="true" hidden><span data-feedback-text></span><button type="button" data-dismiss-feedback aria-label="Tutup pesan"><x-icon name="close"/></button></div>
